using System;
using System.Collections.Generic;
using System.IO;
using System.Reflection;
using System.Text.Json;
using RecursiveAI.OneHtml.Accessibility.Aria;

namespace RecursiveAI.OneHtml.Accessibility.Validation.Rules;

// axe "aria-allowed-role" (a best practice): the explicit role must be one ARIA in HTML allows on the element
// ("Document conformance requirements for use of ARIA attributes in HTML", W3C Recommendation). The table's rows are in
// Rules/Data/allowed-roles.json (generated by tools/validation/generate-allowed-roles.py); rows that depend on context
// are resolved here. The implicit role of an element is always allowed, since the table lists it as "not recommended"
// rather than forbidden.
internal sealed class AriaAllowedRoleRule : AriaRule
{
    private const string Html = "http://www.w3.org/1999/xhtml";

    private static readonly Lazy<Dictionary<string, (bool Any, HashSet<string> Roles)>> s_rows = new(LoadRows);

    public AriaAllowedRoleRule()
        : base(
            "aria-allowed-role",
            "The role attribute of an element should be one that ARIA in HTML allows on that element.",
            "Remove the role, or use an element that suits the role.",
            null,
            "Changing the role changes what the element means to users, and which meaning is intended is the author's call.")
    {
    }

    public override void Evaluate(CheckContext context, RuleReporter reporter)
    {
        int counter = 0;
        foreach (AxNode node in context.Tree.Nodes)
        {
            if ((++counter & 1023) == 0)
            {
                reporter.CancellationToken.ThrowIfCancellationRequested();
            }

            Node el = node.DomNode;
            if (node.Kind != AxNodeKind.Element || !context.IsExposed(el))
            {
                continue;
            }

            NodeRole nr = context.Tree.Roles[el];
            if (nr.ExplicitRole is not { } role || el.GetAttribute("role") is null)
            {
                continue;
            }

            (bool any, HashSet<string>? roles) = AllowedFor(context, node, nr);
            if (roles is null && !any)
            {
                continue; // no row for this element: nothing to compare with
            }

            string name = role.Name;
            if (any || (roles?.Contains(name) ?? false) || (nr.ImplicitRole?.Name == name) || (name == "image" && (roles?.Contains("img") ?? false)))
            {
                reporter.Passed(el);
            }
            else
            {
                reporter.Failed(el, "The role " + name + " is not allowed on a " + el.LocalName + " element.", [new Finding("role", name, name + " is not one of the roles ARIA in HTML allows on " + el.LocalName + ".")]);
            }
        }
    }

    private static (bool Any, HashSet<string>? Roles) AllowedFor(CheckContext c, AxNode node, NodeRole nr)
    {
        Node el = node.DomNode;
        if (el.NamespaceURI == "http://www.w3.org/2000/svg")
        {
            return Row("el-svg");
        }

        if (el.NamespaceURI != Html)
        {
            return (false, null);
        }

        string tag = el.LocalName;
        if (tag.Contains('-', StringComparison.Ordinal))
        {
            return (true, null); // autonomous custom element: any role unless ElementInternals sets one
        }

        Node parent = el.ParentElement;
        switch (tag)
        {
            case "a":
                return Row(el.HasAttribute("href") ? "el-a" : "el-a-no-href");
            case "area":
                return Row(el.HasAttribute("href") ? "el-area" : "el-area-no-href");
            case "h1" or "h2" or "h3" or "h4" or "h5" or "h6":
                return Row("el-h1-h6");
            case "div":
                return !parent.IsNull && parent.LocalName == "dl" ? Set("none", "presentation") : (true, null);
            case "header":
                return Set("group", "none", "presentation", "generic", "banner");
            case "footer":
                return Set("group", "none", "presentation", "generic", "contentinfo", "doc-footnote");
            case "body":
                return Set("generic");
            case "figure":
                return HasDescendant(el, "figcaption") ? Set("figure", "doc-example") : (true, null);
            case "li":
                return !parent.IsNull && c.Tree.Roles[parent].Role is { Name: "list" } ? Set("listitem") : (true, null);
            case "summary":
                return !parent.IsNull && parent.LocalName == "details" && FirstSummary(parent) == el ? Set() : (true, null);
            case "td" or "th" or "tr":
                return TableCellRow(c, el, tag);
            case "select":
                return el.HasAttribute("multiple") || int.TryParse(el.GetAttribute("size"), out int size) && size > 1 ? Row("el-select-multiple-or-size-greater-1", "listbox") : Set("menu", "combobox");
            case "img":
                if (node.Name.IsEmpty)
                {
                    return Set("none", "presentation", "img", "image");
                }

                return Row("el-img");
            case "input":
                return InputRow(el);
            case "label" or "selectedcontent" or "textarea" or "progress" or "main" or "details" or "datalist" or "optgroup" or "option" or "meter":
                return tag is "label" or "selectedcontent" ? (false, null) : Set();
            default:
                return Row("el-" + tag);
        }
    }

    private static (bool, HashSet<string>?) Set(params string[] roles) => (false, new HashSet<string>(roles, StringComparer.Ordinal));

    private static (bool, HashSet<string>?) Row(string id, params string[] extra)
    {
        if (!s_rows.Value.TryGetValue(id, out (bool Any, HashSet<string> Roles) row))
        {
            return (false, null);
        }

        if (extra.Length == 0)
        {
            return (row.Any, row.Roles);
        }

        var roles = new HashSet<string>(extra, StringComparer.Ordinal);
        return (row.Any, roles);
    }

    private static (bool, HashSet<string>?) InputRow(Node el)
    {
        string type = (el.GetAttribute("type") ?? "text").Trim();
        string[] known = ["button", "checkbox", "color", "date", "datetime-local", "email", "file", "hidden", "image", "month", "number", "password", "radio", "range", "reset", "search", "submit", "tel", "text", "time", "url", "week"];
        string lower = "text";
        foreach (string k in known)
        {
            if (System.Text.Ascii.EqualsIgnoreCase(type, k))
            {
                lower = k;
            }
        }

        if (el.HasAttribute("list") && lower is "text" or "search" or "tel" or "url" or "email")
        {
            return Set("combobox");
        }

        return Row("el-input-" + lower);
    }

    private static (bool, HashSet<string>?) TableCellRow(CheckContext c, Node el, string tag)
    {
        for (Node a = el.ParentElement; !a.IsNull; a = a.ParentElement)
        {
            if (a.LocalName == "table" && a.NamespaceURI == Html)
            {
                string? role = c.Tree.Roles[a].Role?.Name;
                return role switch
                {
                    "table" => tag == "tr" ? Set("row") : tag == "td" ? Set("cell") : Set("columnheader", "rowheader", "cell"),
                    "grid" or "treegrid" => tag == "tr" ? Set("row") : tag == "td" ? Set("gridcell") : Set("columnheader", "rowheader", "gridcell"),
                    _ => (true, null),
                };
            }
        }

        return (true, null);
    }

    private static bool HasDescendant(Node el, string tag)
    {
        foreach (Node d in el.DescendantElements)
        {
            if (d.LocalName == tag && d.NamespaceURI == Html)
            {
                return true;
            }
        }

        return false;
    }

    private static Node FirstSummary(Node details)
    {
        foreach (Node ch in details.Children)
        {
            if (ch.LocalName == "summary" && ch.NamespaceURI == Html)
            {
                return ch;
            }
        }

        return default;
    }

    private static Dictionary<string, (bool, HashSet<string>)> LoadRows()
    {
        Assembly assembly = typeof(AriaAllowedRoleRule).Assembly;
        using Stream stream = assembly.GetManifestResourceStream("Rules.allowed-roles.json")
            ?? throw new InvalidOperationException("Missing embedded data: allowed-roles.json");
        using JsonDocument doc = JsonDocument.Parse(stream);
        var result = new Dictionary<string, (bool, HashSet<string>)>(StringComparer.Ordinal);
        foreach (JsonProperty row in doc.RootElement.GetProperty("rows").EnumerateObject())
        {
            var roles = new HashSet<string>(StringComparer.Ordinal);
            foreach (JsonElement r in row.Value.GetProperty("roles").EnumerateArray())
            {
                roles.Add(r.GetString()!);
            }

            result[row.Name] = (row.Value.GetProperty("any").GetBoolean(), roles);
        }

        return result;
    }
}
